#!/usr/bin/env python3
"""
Modernized Climate Data Analysis Script - Python 3
Analyzes temperature data from multiple weather stations
"""

from pathlib import Path
import configparser
import pandas as pd
import numpy as np


class ClimateAnalyzer:
    def __init__(self, config_path="config.ini"):
        self.config = configparser.ConfigParser()
        self.config.read(config_path, encoding='utf-8')
        self.data_cache = {}

    def load_temperature_data(self, filename):
        """Load temperature data using modern pandas API"""
        df = pd.read_csv(filename, encoding='utf-8')
        df['date'] = pd.to_datetime(df['date'], format='%Y-%m-%d')
        return df

    def calculate_mean_temperature(self, temperature_series):
        """Calculate mean temperature from a series"""
        return np.mean(temperature_series)

    def run_analysis(self):
        """Main analysis pipeline"""
        print("Starting climate analysis...")

        try:
            data_file = Path('climate_analyzer/sample_data/climate_data.csv')

            if not data_file.exists():
                raise FileNotFoundError(f"Data file not found: {data_file}")

            data = self.load_temperature_data(str(data_file))

            for station_id, group in data.groupby('station_id'):
                mean_temp = self.calculate_mean_temperature(group['temperature'])
                print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")

        except Exception as e:
            print(f"Error occurred: {e}")
            raise

        print("Analysis completed successfully!")


if __name__ == "__main__":
    analyzer = ClimateAnalyzer()
    analyzer.run_analysis()

